import java.util.Scanner;

public class B {
    static class Analyzer {
        private int len = 0;
        private int max = 0;
        private int count = 0;
        private boolean inside = false;

        void handle(char c) {
            if (c == '_') {
                if (len > 0) {
                    if (inside) count++;
                    else max = Math.max(max, len);
                }
                len = 0;
            } else if (c == '(') {
                if (len > 0) max = Math.max(max, len);
                len = 0;
                inside = true;
            } else if (c == ')') {
                if (len > 0) count++;
                len = 0;
                inside = false;
            } else {
                len++;
            }
        }

        void finish() {
            if (len > 0) max = Math.max(max, len);
        }

        void print() {
            System.out.println(max + " " + count);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        sc.nextInt();
        String s = sc.next();

        Analyzer analyzer = new Analyzer();
        for (char c : s.toCharArray()) analyzer.handle(c);
        analyzer.finish();
        analyzer.print();
    }
}
